architecture.h4_f:
msg = CBOR{v:1, rubutu, amsa_zuwa, aika_a}
ct = AES-GCM-256-Encrypt(k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/saƙonni {ciphertext: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, rubutu, amsa?, zaren_id?, ambaton?, aiko_at}
ct = AES-GCM-256-Encrypt (key_key, nonce, pt, aad=hex(room_id))
waya = CBOR{
  v: 1,
  sifartext: hex(ct), // tsayi mai tsayi
  babu: hex (12 B),
  sender_pseudo: hex(16 B),
  aika_at: unix_ms
}

cryptoWire.h5_f:
waje = CBOR{
  source_node: hex32,
  target_user: int64,
  inner_ciphertext: bytes,
  ciki_nonce: bytes,
  aika_at: unix_ms
}
sig = Ed25519-Sign (source_priv, waje)
POST / tarayya/ba da {ambulaf: waje, sig: hex64}

auth.h1_f:
POST /api/authentication/register
  {sunan mai amfani, kalmar sirri, x25519_public_key, display_name, phone?, email?, avatar_emoji }

An Ƙirƙiri Amsa 201:
  { access_token, refresh_token, user_id, sunan mai amfani, ... }

auth.h3_f:
access_token biya:
  {sub: user_id, jti: device_id, typ: "access", exp: now + 15min}
refresh_token kaya:
  {s: user_id, jti: device_id, buga: "refresh", exp: yanzu + 30d }

HS256- sa hannu tare da sirrin 64-byte na kumburi daga .env

auth.h4_f:
register_begin(): kalubale = rand(32)
                    zažužžukan = {rp.id, user.id, pubKeyCredParams, kalubale}
                    mayar da zažužžukan

register_finish(shaida):
  tabbatar da shaida akan TPM / Amintaccen tushen Enclave CA
  kantin sayar da { credential_id, public_key, counter: 0 }

auth.h7_f:
POST /api/authentication/qr/begin
  → {ba komai: hex 128-bit, ttl: 60}
QR abin biya = {babu, mai amfani_id, uwar garken: "https://node.example"}

POST /api/authentication/qr/verify { nonce }
  → sabuwar na'ura mai rijista; JWT sun dawo.

